#!/usr/bin/env bash
# Question 1: Kustomize: HPA in base, patched in prod. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

rm -rf /opt/course/kustomize/${Q1_APP}-envs
mkdir -p /opt/course/kustomize/${Q1_APP}-envs
chown -R ubuntu:ubuntu /opt/course
mkdir -p /opt/course/kustomize/${Q1_APP}-envs/base /opt/course/kustomize/${Q1_APP}-envs/overlays/staging /opt/course/kustomize/${Q1_APP}-envs/overlays/prod
cat > /opt/course/kustomize/${Q1_APP}-envs/base/deployment.yaml <<EOF
apiVersion: apps/v1
kind: Deployment
metadata:
  name: ${Q1_APP}
spec:
  replicas: 1
  selector:
    matchLabels: { app: ${Q1_APP} }
  template:
    metadata:
      labels: { app: ${Q1_APP} }
    spec:
      containers:
        - name: web
          image: nginx:1.27-alpine
          resources:
            requests: { cpu: 20m, memory: 16Mi }
EOF
cat > /opt/course/kustomize/${Q1_APP}-envs/base/scaling-config.yaml <<EOF
apiVersion: v1
kind: ConfigMap
metadata:
  name: ${Q1_APP}-scaling
data:
  MIN_REPLICAS: "1"
  MAX_REPLICAS: "4"
EOF
cat > /opt/course/kustomize/${Q1_APP}-envs/base/kustomization.yaml <<EOF
apiVersion: kustomize.config.k8s.io/v1beta1
kind: Kustomization
resources:
  - deployment.yaml
  - scaling-config.yaml
EOF
cat > /opt/course/kustomize/${Q1_APP}-envs/overlays/staging/kustomization.yaml <<EOF
apiVersion: kustomize.config.k8s.io/v1beta1
kind: Kustomization
namespace: ${Q1_APP}-staging
resources:
  - ../../base
labels:
  - pairs:
      env: staging
EOF
cat > /opt/course/kustomize/${Q1_APP}-envs/overlays/prod/resources.yaml <<EOF
apiVersion: apps/v1
kind: Deployment
metadata:
  name: ${Q1_APP}
spec:
  template:
    spec:
      containers:
        - name: web
          resources:
            requests: { cpu: 50m, memory: 32Mi }
EOF
cat > /opt/course/kustomize/${Q1_APP}-envs/overlays/prod/kustomization.yaml <<EOF
apiVersion: kustomize.config.k8s.io/v1beta1
kind: Kustomization
namespace: ${Q1_APP}-production
resources:
  - ../../base
labels:
  - pairs:
      env: prod
patches:
  - path: resources.yaml
EOF
chown -R ubuntu:ubuntu /opt/course
for ns in ${Q1_APP}-staging ${Q1_APP}-production; do
  kubectl delete namespace "$ns" --ignore-not-found --wait=true >/dev/null
  kubectl create namespace "$ns" >/dev/null
done
kubectl apply -k /opt/course/kustomize/${Q1_APP}-envs/overlays/staging >/dev/null
kubectl apply -k /opt/course/kustomize/${Q1_APP}-envs/overlays/prod >/dev/null
kubectl -n ${Q1_APP}-staging get configmap ${Q1_APP}-scaling >/dev/null
kubectl -n ${Q1_APP}-production get configmap ${Q1_APP}-scaling >/dev/null
: "${Q1_APP}"
